// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }
    function testFuzz_property(address recipient, uint8 numCalls) public {
        vm.assume(numCalls > 0 && numCalls <= 10);
        vm.assume(recipient != address(0));

        for(uint i = 0; i < numCalls; i++) {
            c.newGrantProposal(recipient, 100);
        }

        uint pc = c.proposalCount();
        assertTrue(pc == numCalls);
    }
}
